import React from 'react';
import { Card } from '@material-ui/core';
import { Table } from 'reactstrap';
import ExpandMoreIcon from '@material-ui/icons/ExpandMore';
import ExpandLessIcon from '@material-ui/icons/ExpandLess';
import colors from 'config/colors';
import { employeeStatic } from 'config/constants';

// Shared collapse chrome for every panel below the grid. Teachers viewing their own timetable
// (readOnly) mostly just want the grid itself - the allocation/collision breakdowns are
// admin-oriented detail - so those panels start collapsed there; the admin's own Generate Time
// Table page (not readOnly) keeps everything expanded since that's the page for working through
// the detail.
const CollapsibleCard = ({ title, collapsible, defaultOpen, children }) => {
  const [collapsed, setCollapsed] = React.useState(!!collapsible && !defaultOpen);
  return (
    <Card className="mb-3">
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          padding: '14px 16px',
          ...(collapsible && { cursor: 'pointer' }),
        }}
        {...(collapsible && { onClick: () => setCollapsed(prev => !prev), role: 'button' })}>
        <b>{title}</b>
        {collapsible && (
          <span
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 2,
              fontSize: 12,
              color: colors.accent,
              fontWeight: 'bold',
            }}>
            {collapsed ? 'Show' : 'Hide'}
            {collapsed ? <ExpandMoreIcon fontSize="small" /> : <ExpandLessIcon fontSize="small" />}
          </span>
        )}
      </div>
      {!collapsed && <div style={{ padding: '0 16px 16px' }}>{children}</div>}
    </Card>
  );
};

// Local Mon-Sat day list for the grid header/columns.
const GRID_DAYS = [
  { label: 'Monday', value: 'MON' },
  { label: 'Tuesday', value: 'TUE' },
  { label: 'Wednesday', value: 'WED' },
  { label: 'Thursday', value: 'THU' },
  { label: 'Friday', value: 'FRI' },
  { label: 'Saturday', value: 'SAT' },
];

// Periods shown on the grid. LUNCH is a purely visual divider row - it is
// never sent to the backend as a timePeriod value.
// Period 9 and Period 10 are hidden from both the edit and read-only views.
export const TIMETABLE_PERIODS = [
  'Period 1',
  'Period 2',
  'Period 3',
  'Period 4',
  'LUNCH',
  'Period 5',
  'Period 6',
  'Period 7',
  'Period 8',
];

const COLLISION_COLOR_MAP = {
  RED: '#ffcccc',
  GREEN: '#ccffcc',
  PINK: '#ffd6eb',
  ORANGE: '#ffe0b3',
  PURPLE: '#e0ccff',
  TEAL: '#ccf2f0',
  YELLOW: '#fff5b3',
  BROWN: '#e6d2b3',
  CYAN: '#ccf2ff',
  MAGENTA: '#ffccf2',
};

const findCell = (cells, day, timePeriod) => cells?.find(c => c.day === day && c.timePeriod === timePeriod);

const StatItem = ({ label, value }) => (
  <div style={{ textAlign: 'center', minWidth: 100 }}>
    <div style={{ fontSize: 20, fontWeight: 'bold', color: colors.accent }}>{value ?? '--'}</div>
    <div style={{ color: '#6b778a', fontSize: 12 }}>{label}</div>
  </div>
);

const StatusPanelContent = ({ data }) => (
  <div style={{ display: 'flex', justifyContent: 'space-around', flexWrap: 'wrap' }}>
    <StatItem label="Total Periods" value={data?.totalPeriods} />
    <StatItem label="Allocated" value={data?.allocatedPeriods} />
    <StatItem label="Unassigned" value={data?.emptyPeriods} />
    <StatItem label="Collisions" value={data?.collisionCount} />
  </div>
);

const GridCell = ({ cell, readOnly, onCellClick }) => {
  if (!cell) {
    return readOnly ? (
      <span style={{ color: '#b3bac3', fontStyle: 'italic', fontSize: 12 }}>No subject assigned</span>
    ) : (
      <span style={{ color: '#aaa', fontStyle: 'italic' }}>+ Add subject</span>
    );
  }
  return (
    <div>
      <div style={{ fontWeight: 'bold', fontSize: 13, color: '#2b2b2b' }}>{cell.subject}</div>
      <div style={{ fontSize: 10, color: '#98a2ad' }}>{cell.subjectCode}</div>
      {!!cell.teacherNames?.length && (
        <div style={{ fontSize: 12, color: colors.accent, marginTop: 2 }}>{cell.teacherNames.join(', ')}</div>
      )}
    </div>
  );
};

const TimetableGrid = ({ cells, onCellClick, readOnly }) => (
  <Card className="mb-3">
    <div className="table-responsive">
      <Table bordered className="text-center mb-0" style={{ tableLayout: 'fixed', minWidth: 720 }}>
        <thead>
          <tr style={{ background: colors.accent }}>
            <th style={{ color: '#fff', width: '10%', border: '1px solid rgba(255,255,255,0.35)' }}>Period</th>
            {GRID_DAYS.map(d => (
              <th key={d.value} style={{ color: '#fff', border: '1px solid rgba(255,255,255,0.35)' }}>
                {d.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {TIMETABLE_PERIODS.map(period => {
            if (period === 'LUNCH') {
              return (
                <tr key={period} style={{ background: '#ffe9b3', fontWeight: 'bold' }}>
                  <td>Lunch</td>
                  {GRID_DAYS.map(d => (
                    <td key={d.value}>LUNCH</td>
                  ))}
                </tr>
              );
            }
            return (
              <tr key={period}>
                <td style={{ background: '#f5f2f8', fontWeight: 'bold' }}>{period}</td>
                {GRID_DAYS.map(d => {
                  const cell = findCell(cells, d.value, period);
                  const bg = cell?.collisionColor ? COLLISION_COLOR_MAP[cell.collisionColor] : undefined;
                  return (
                    <td
                      key={d.value}
                      onClick={() => !readOnly && onCellClick(d.value, period, cell)}
                      style={{
                        cursor: readOnly ? 'default' : 'pointer',
                        height: 68,
                        verticalAlign: 'middle',
                        ...(bg && { background: bg }),
                      }}>
                      <GridCell cell={cell} readOnly={readOnly} />
                    </td>
                  );
                })}
              </tr>
            );
          })}
        </tbody>
      </Table>
    </div>
  </Card>
);

const SubjectAllocationContent = ({ subjectAllocations }) => (
  <div className="table-responsive">
    <Table bordered size="sm" className="mb-0">
      <thead>
        <tr>
          <th>Subject</th>
          <th>{employeeStatic}</th>
          <th>Allocated</th>
          <th>Pending</th>
        </tr>
      </thead>
      <tbody>
        {subjectAllocations?.length ? (
          subjectAllocations.map(s => (
            <tr key={s.subjectId}>
              <td>
                {s.subject} {s.subjectCode && <span style={{ color: '#98a2ad' }}>({s.subjectCode})</span>}
              </td>
              <td>{s.teacherName || '-'}</td>
              <td>{s.allocatedPeriods}</td>
              <td>{s.pendingPeriods}</td>
            </tr>
          ))
        ) : (
          <tr>
            <td colSpan={4} className="text-center">
              No subjects found.
            </td>
          </tr>
        )}
      </tbody>
    </Table>
  </div>
);

const TeacherAllocationContent = ({ teacherAllocations }) => (
  <div className="table-responsive">
    <Table bordered size="sm" className="mb-0">
      <thead>
        <tr>
          <th>{employeeStatic}</th>
          <th>Periods</th>
          <th>Max</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {teacherAllocations?.length ? (
          teacherAllocations.map(t => (
            <tr key={t.teacherId}>
              <td>{t.teacherName}</td>
              <td>{t.allocatedPeriods}</td>
              <td>{t.maximumPeriods}</td>
              <td>{t.maximumExceeded && <span style={{ color: '#c62828', fontWeight: 'bold' }}>Over limit</span>}</td>
            </tr>
          ))
        ) : (
          <tr>
            <td colSpan={4} className="text-center">
              No {employeeStatic.toLowerCase()}s found.
            </td>
          </tr>
        )}
      </tbody>
    </Table>
  </div>
);

// The collision color is only a visual key that ties a list entry back to its highlighted
// cells in the grid above - it has no meaning of its own (a "GREEN" collision is exactly as
// real as a "RED" one), so the label shown to teachers/admins is a plain sequential number.
const dayLabel = day => GRID_DAYS.find(d => d.value === day)?.label || day;

const CollisionsContent = ({ collisions }) =>
  collisions?.length ? (
    collisions.map((c, idx) => (
      <div key={c.collisionKey} style={{ borderBottom: '1px solid #eee', padding: '6px 0', fontSize: 13 }}>
        <span
          style={{
            display: 'inline-block',
            width: 12,
            height: 12,
            borderRadius: 2,
            marginRight: 6,
            verticalAlign: 'middle',
            background: COLLISION_COLOR_MAP[c.color] || '#ccc',
          }}
        />
        <b>Collision {idx + 1}:</b> {employeeStatic} {c.teacherName} is booked for two classes at the same time (
        {dayLabel(c.day)} - {c.timePeriod}):
        {c.entries?.map((e, i) => (
          <div key={i} style={{ paddingLeft: 18 }}>
            {e.courseName}-{e.batchName} &rarr; {e.subject}
          </div>
        ))}
      </div>
    ))
  ) : (
    <div style={{ color: '#6b778a' }}>No collisions.</div>
  );

const TimetableAllocationGrid = ({ data, onCellClick, readOnly = false }) => {
  if (!data) return null;
  const collisionCount = data.collisions?.length || 0;
  return (
    <>
      <CollapsibleCard title="Overview" collapsible={readOnly} defaultOpen>
        <StatusPanelContent data={data} />
      </CollapsibleCard>
      <TimetableGrid cells={data.timetable} onCellClick={onCellClick} readOnly={readOnly} />
      <CollapsibleCard title="Subject Allocation" collapsible={readOnly}>
        <SubjectAllocationContent subjectAllocations={data.subjectAllocations} />
      </CollapsibleCard>
      <CollapsibleCard title={`${employeeStatic} Allocation`} collapsible={readOnly}>
        <TeacherAllocationContent teacherAllocations={data.teacherAllocations} />
      </CollapsibleCard>
      <CollapsibleCard title={`Collisions${collisionCount ? ` (${collisionCount})` : ''}`} collapsible={readOnly}>
        <CollisionsContent collisions={data.collisions} />
      </CollapsibleCard>
    </>
  );
};

export default TimetableAllocationGrid;
