import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useHistory, useLocation } from 'react-router-dom';
import {
  formCourseSelectList,
  formResMessage,
  getGlobalCurrentBatchUtils,
  getGlobalSchoolUtils,
} from 'utils/commonFunc';
import {
  fetchBatchCourseService,
  fetchTimetableAllocationApi,
  saveTimetableAllocationCellApi,
} from 'actions/admin/courses';
import CustomSelect from 'components/CustomSelect';
import { Col, Row } from 'reactstrap';
import constants, { courseStatic } from 'config/constants';
import { showToast } from 'actions/admin/auth';
import TimetableAllocationGrid from './TimetableAllocationGrid';
import SubjectPickerModal from './SubjectPickerModal';
import { LoadingCard } from '../Common/Loader';
import { encodeUrlId, decodeUrlId } from 'utils/urlIdCodec';

const TimeTablePage = () => {
  const dispatch = useDispatch();
  const history = useHistory();
  const location = useLocation();
  const authStore = useSelector(state => state.auth);
  const { loggedUserToken, loggedUserSchool, loggedUserRole, loggedUserId } = authStore;
  const courseStore = useSelector(state => state.courses);
  const batchCourseList = courseStore?.batchCourseList || [];

  const getUrlCourseId = () => decodeUrlId(new URLSearchParams(location.search).get('courseId'));

  const [courseId, setCouseId] = useState(getUrlCourseId);
  const [fethcing, setFetchingLoading] = useState(false);
  const [timetableData, setTimetableData] = useState(null);
  const [picker, setPicker] = useState({ open: false, day: null, timePeriod: null, existingCell: null });

  const fetchTimetableAllocation = async () => {
    const globalSchool = getGlobalSchoolUtils();
    const batchData = getGlobalCurrentBatchUtils();
    const schoolId = globalSchool.schoolId;
    const batchId = batchData?.batchId;
    if (batchId && courseId && schoolId) {
      setFetchingLoading(true);
      try {
        const res = await fetchTimetableAllocationApi({ schoolId, courseId, batchId, token: loggedUserToken });
        setTimetableData(res.data);
      } catch (err) {
        dispatch(showToast(formResMessage(err), 'error'));
      }
      setFetchingLoading(false);
    }
  };

  useEffect(() => {
    const globalSchool = getGlobalSchoolUtils();
    const batchData = getGlobalCurrentBatchUtils();
    dispatch(
      fetchBatchCourseService({
        schoolId: globalSchool?.schoolId || loggedUserSchool,
        token: loggedUserToken,
        batchId: batchData?.batchId,
      })
    );
  }, []);

  useEffect(() => {
    fetchTimetableAllocation();
  }, [courseId]);

  // Restore the class from the URL once the batch's class list loads. If the URL's
  // courseId doesn't match any class in this batch (stale link, removed class, or
  // no courseId at all), fall back to the first class instead of leaving it empty.
  useEffect(() => {
    if (batchCourseList?.length && !batchCourseList.some(c => c.courseId === courseId)) {
      handleCourseChange(batchCourseList[0].courseId);
    }
  }, [batchCourseList]);

  const courseArr = batchCourseList?.length ? formCourseSelectList(batchCourseList) : [];

  const handleCourseChange = courseId => {
    setCouseId(courseId);
    const params = new URLSearchParams(location.search);
    if (courseId) {
      params.set('courseId', encodeUrlId(courseId));
    } else {
      params.delete('courseId');
    }
    history.replace(`${location.pathname}?${params.toString()}`);
  };

  // Clicking a cell always opens the picker - whether it's empty (add) or already
  // assigned (replace/clear). No separate "edit mode" toggle: matches the BE demo
  // page and keeps the grid itself directly editable, which is simpler to use.
  // A teacher can change only a free period or one of their own subjects (the server refuses the rest, so say so up front).
  const openSubjectPicker = (day, timePeriod, existingCell) => {
    const takenBy = existingCell?.teacherIds || [];
    if (loggedUserRole === constants.roles.teacher && takenBy.length && !takenBy.includes(Number(loggedUserId))) {
      dispatch(showToast('This period belongs to another teacher', 'warning'));
      return;
    }
    setPicker({ open: true, day, timePeriod, existingCell });
  };

  const closeSubjectPicker = () => {
    setPicker({ open: false, day: null, timePeriod: null, existingCell: null });
  };

  const handleSelectSubject = async subjectId => {
    const globalSchool = getGlobalSchoolUtils();
    const batchData = getGlobalCurrentBatchUtils();
    const { day, timePeriod } = picker;
    closeSubjectPicker();
    try {
      await saveTimetableAllocationCellApi({
        schoolId: globalSchool.schoolId,
        courseId,
        batchId: batchData?.batchId,
        day,
        timePeriod,
        subjectId,
        token: loggedUserToken,
      });
      await fetchTimetableAllocation();
    } catch (err) {
      dispatch(showToast(formResMessage(err), 'error'));
    }
  };

  return (
    <div className="content">
      <Row>
        <Col md={10}>
          <CustomSelect
            label={`Select ${courseStatic}`}
            name="courseId"
            value={courseId}
            onChange={(name, selectItem) => handleCourseChange(selectItem)}
            options={courseArr}
            isClearable
          />
        </Col>
      </Row>
      <br />
      {fethcing && <LoadingCard />}
      {!fethcing && <TimetableAllocationGrid data={timetableData} onCellClick={openSubjectPicker} />}
      <SubjectPickerModal
        open={picker.open}
        day={picker.day}
        timePeriod={picker.timePeriod}
        existingCell={picker.existingCell}
        subjects={timetableData?.subjectAllocations}
        onSelect={handleSelectSubject}
        onClose={closeSubjectPicker}
      />
    </div>
  );
};

export default TimeTablePage;
