import React from 'react';
import { Dialog, DialogTitle, DialogContent, DialogActions, List, ListItem, ListItemText } from '@material-ui/core';
import CustomButton from 'components/CustomButton';

// Modal used when a timetable grid cell is clicked - lets the admin assign a
// subject to that day/period, replace an already-assigned subject, or clear it.
// Subjects are not filtered by "already assigned" - a subject can recur across
// multiple periods in a week, so the full course subject list is always shown.
const SubjectPickerModal = ({ open, day, timePeriod, existingCell, subjects, onSelect, onClose }) => {
  return (
    <Dialog open={open} onClose={onClose} maxWidth="xs" fullWidth>
      <DialogTitle>
        Select Subject - {day} {timePeriod}
      </DialogTitle>
      <DialogContent dividers>
        <List>
          {existingCell && (
            <ListItem button divider onClick={() => onSelect(null)}>
              <ListItemText primaryTypographyProps={{ style: { color: '#c62828', fontWeight: 'bold' } }}>
                Clear this cell
              </ListItemText>
            </ListItem>
          )}
          {subjects?.length ? (
            subjects.map(s => (
              <ListItem button divider key={s.subjectId} onClick={() => onSelect(s.subjectId)}>
                <ListItemText secondary={s.teacherName || undefined}>
                  {s.subject} <span style={{ color: '#98a2ad', fontSize: 12 }}>({s.subjectCode})</span>
                </ListItemText>
              </ListItem>
            ))
          ) : (
            <ListItem>
              <ListItemText style={{ color: '#6b778a' }}>No subjects available for this course.</ListItemText>
            </ListItem>
          )}
        </List>
      </DialogContent>
      <DialogActions>
        <CustomButton name="Cancel" variant="outlined" color="default" onClick={onClose} />
      </DialogActions>
    </Dialog>
  );
};

export default SubjectPickerModal;
